// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, Fixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, IProduct} from "../src/Product.sol";

contract MockOracle is IOracleProvider {
    OracleVersion private _ov;
    constructor() {
        _ov = OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
    function sync() external view returns (OracleVersion memory) { return _ov; }
    function currentVersion() external view returns (OracleVersion memory) { return _ov; }
    function atVersion(uint256) external view returns (OracleVersion memory) { return _ov; }
}

contract InvMutTest is Test {
    Product c;
    uint64 internal coordinatorIdOfProduct;
    address internal productOwnerAddr;

    // The test contract acts as C's controller (C records msg.sender of initialize).
    function paused() external view returns (bool) { return false; }
    function coordinatorFor(IProduct) external view returns (uint256) { return coordinatorIdOfProduct; }
    function owner(uint256) external view returns (address) { return productOwnerAddr; }

    function setUp() public {
        c = new Product();
        MockOracle oracle = new MockOracle();
        PayoffDefinition memory pd; // default: Linear / Long, valid
        JumpRateUtilizationCurve memory curve;
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "P",
            symbol: "P",
            payoffDefinition: pd,
            oracle: oracle,
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: curve
        });
        c.initialize(info);
    }

    function testFuzz_property(
        uint256 newMaintenance,
        address ownerAddr,
        address caller,
        uint64 coordinatorId
    ) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != ownerAddr);
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        vm.assume(ownerAddr != address(this));
        vm.assume(ownerAddr != address(c));

        coordinatorIdOfProduct = coordinatorId;
        productOwnerAddr = ownerAddr;

        // RULE: a caller that is NOT the product's coordinator owner must NEVER be able to
        // complete updateMaintenance: the call must revert and maintenance() stays unchanged.
        UFixed18 before = c.maintenance();

        vm.prank(caller);
        bool ok;
        try c.updateMaintenance(UFixed18.wrap(newMaintenance)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && UFixed18.unwrap(c.maintenance()) == UFixed18.unwrap(before));
    }
}
